def test_multi_visit_capacity_is_inclusive_and_shared():
    day = date(2024, 1, 1)
    capacity = {day: 2}
    # Three visits nominally fall on the same capacity day only via moves.
    closed = {date(2024, 2, 1)}
    visits = plan_visits(
        first_day=day,
        offsets_months=[0],
        hour=9,
        minute=0,
        timezone="America/New_York",
        closed_days=closed,
        capacity=capacity,
    )
    assert visits[0]["local"][:10] == "2024-01-01"

    capacity = {date(2024, 3, 1): 1, date(2024, 3, 2): 0}
    closed = {date(2024, 2, 29)}
    visits = plan_visits(
        first_day=date(2024, 1, 29),
        offsets_months=[2, 1],
        hour=9,
        minute=0,
        timezone="America/New_York",
        closed_days=closed,
        capacity=capacity,
    )
    # Offset 2 nominal 2024-03-29; offset 1 nominal 2024-02-29 closed -> 03-01.
    assert [visit["local"][:10] for visit in visits] == ["2024-03-29", "2024-03-01"]

    capacity = {date(2024, 3, 1): 1, date(2024, 3, 2): 0}
    closed = {date(2024, 2, 28), date(2024, 2, 29)}
    visits = plan_visits(
        first_day=date(2024, 1, 28),
        offsets_months=[1, 0],
        hour=9,
        minute=0,
        timezone="America/New_York",
        closed_days=closed,
        capacity=capacity,
    )
    assert [visit["local"][:10] for visit in visits] == ["2024-03-01", "2024-01-28"]

    # Two visits contend for one slot: the second skips the zero day too.
    capacity = {date(2024, 3, 1): 1, date(2024, 3, 2): 0}
    closed = {date(2024, 2, 28), date(2024, 2, 29)} | {
        date(2024, 3, 28) + timedelta(days=n) for n in range(4)
    }
    visits = plan_visits(
        first_day=date(2024, 1, 28),
        offsets_months=[1],
        hour=9,
        minute=0,
        timezone="America/New_York",
        closed_days=closed,
        capacity=capacity,
    )
    assert visits[0]["local"][:10] == "2024-03-01"


def test_competing_visits_exhaust_slot_and_skip_zero_day():
    capacity = {date(2024, 2, 29): 1, date(2024, 3, 1): 0}
    closed = {date(2024, 2, 28)}
    original = dict(capacity)
    visits = plan_visits(
        first_day=date(2024, 1, 28),
        offsets_months=[1, 0],
        hour=8,
        minute=15,
        timezone="America/New_York",
        closed_days=closed | {date(2024, 1, 28) + timedelta(days=n) for n in range(32)},
        capacity=capacity,
    )
    # Offset 1: 02-28 closed -> 02-29 (uses last slot).
    # Offset 0: 01-28..02-28 closed -> 02-29 full -> 03-01 zero -> 03-02.
    assert [visit["local"] for visit in visits] == [
        "2024-02-29T08:15:00-05:00",
        "2024-03-02T08:15:00-05:00",
    ]
    assert capacity == original


