def booking_kwargs(**overrides):
    kwargs = dict(
        on=date(2024, 1, 15),
        first_day=date(2024, 1, 31),
        offsets_months=[0, 1],
        hour=9,
        minute=0,
        timezone="America/New_York",
    )
    kwargs.update(overrides)
    return kwargs


def test_sequential_bookings_contend_for_persistent_slots():
    capacity = {date(2024, 1, 31): 1, date(2024, 2, 29): 1}
    first = book_subject_visits(
        make_subject(), make_protocol(), capacity=capacity, **booking_kwargs()
    )
    assert [visit["local"][:10] for visit in first] == ["2024-01-31", "2024-02-29"]
    assert capacity == {date(2024, 1, 31): 0, date(2024, 2, 29): 0}

    second = book_subject_visits(
        make_subject(), make_protocol(), capacity=capacity, **booking_kwargs()
    )
    assert [visit["local"][:10] for visit in second] == ["2024-02-01", "2024-03-01"]
    # Unlisted dates stay unconstrained and are never inserted.
    assert capacity == {date(2024, 1, 31): 0, date(2024, 2, 29): 0}


def test_same_booking_can_use_multiple_slots_on_one_day():
    capacity = {date(2024, 2, 29): 2}
    closed = {date(2024, 2, 28)} | {
        date(2024, 1, 28) + timedelta(days=n) for n in range(31)
    }
    visits = book_subject_visits(
        make_subject(),
        make_protocol(),
        capacity=capacity,
        closed_days=closed,
        **booking_kwargs(first_day=date(2024, 1, 28), offsets_months=[0, 1]),
    )
    assert [visit["local"][:10] for visit in visits] == ["2024-02-29", "2024-02-29"]
    assert capacity == {date(2024, 2, 29): 0}


def test_later_visit_failure_rolls_back_all_reservations():
    capacity = {date(2024, 1, 31): 1}
    committed = book_subject_visits(
        make_subject(),
        make_protocol(),
        capacity=capacity,
        **booking_kwargs(offsets_months=[0]),
    )
    assert committed[0]["local"][:10] == "2024-01-31"
    assert capacity == {date(2024, 1, 31): 0}

    capacity[date(2024, 3, 31)] = 3
    closed = {date(2024, 4, 30) + timedelta(days=n) for n in range(367)}
    closed_copy = set(closed)
    with pytest.raises(ValueError, match="UNSCHEDULABLE"):
        book_subject_visits(
            make_subject(),
            make_protocol(),
            capacity=capacity,
            closed_days=closed,
            **booking_kwargs(offsets_months=[2, 3]),
        )
    # The earlier successful booking stays committed; the failed one is undone.
    assert capacity == {date(2024, 1, 31): 0, date(2024, 3, 31): 3}
    assert closed == closed_copy


def test_ineligible_subject_raises_with_ordered_reasons_and_keeps_capacity():
    subject = make_subject()
    subject["flags"] = ["PRIOR"]
    subject["labs"] = {"A": 9}
    subject_copy = {
        "birth_date": subject["birth_date"],
        "consents": [dict(c) for c in subject["consents"]],
        "labs": dict(subject["labs"]),
        "flags": list(subject["flags"]),
    }
    protocol = make_protocol()
    capacity = {date(2024, 1, 31): 1}
    with pytest.raises(ValueError) as excinfo:
        book_subject_visits(subject, protocol, capacity=capacity, **booking_kwargs())
    message = str(excinfo.value)
    assert message.startswith("INELIGIBLE:")
    assert message.index("EXCLUSION_PRIOR") < message.index("LAB_A_HIGH")
    assert capacity == {date(2024, 1, 31): 1}
    assert subject == subject_copy
    assert protocol == make_protocol()


